import { useState } from 'react';
import { Film, Type, Sparkles, Wand2, Upload, FolderOpen, Users, Video } from 'lucide-react';
import { useTimelineStore } from '../../store/useTimelineStore';
import { useFontStore } from '../../store/useFontStore';
import { FileButton } from '../Common/controls';
import { importFiles, addTextAtPlayhead } from './mediaImport';
import { TEXT_PRESETS } from '../../engine/presets';

/** Common delivery sizes, also surfaced in the Details panel. */
export const ASPECT_PRESETS: { label: string; width: number; height: number }[] = [
  { label: '9:16 Vertical', width: 1080, height: 1920 },
  { label: '16:9 Landscape', width: 1920, height: 1080 },
  { label: '1:1 Square', width: 1080, height: 1080 },
  { label: '4:5 Portrait', width: 1080, height: 1350 },
  { label: '4:3 Classic', width: 1440, height: 1080 },
  { label: '21:9 Cinema', width: 2560, height: 1080 },
];

type Tab = 'media' | 'text' | 'filters';

/**
 * Left column of the shell, matching CapCut's two-part arrangement:
 *
 *   narrow sidebar -> section switcher (Import / Media / Library ...)
 *   wider panel    -> horizontal icon tabs over contextual content
 *
 * CapCut also lists Stickers, Effects, Transitions, Captions, Adjustment and
 * Templates on that tab strip. Those features do not exist here yet, so they
 * are omitted rather than rendered as dead buttons.
 */
export const Library = () => {
  const [tab, setTab] = useState<Tab>('media');
  const [status, setStatus] = useState<string | null>(null);
  const addFiles = useFontStore((s) => s.addFiles);
  const fonts = useFontStore((s) => s.fonts);
  const clipCount = useTimelineStore((s) => s.clipOrder.length);

  const handleMedia = async (files: File[]) => {
    const { settings: s, playhead } = useTimelineStore.getState();
    setStatus('Importingâ€¦');
    // Import at the playhead so a drop lands where the user is looking.
    const { added, errors } = await importFiles(files, s.fps, { startAt: playhead });
    setStatus(
      errors.length > 0
        ? `${added} added, ${errors.length} failed: ${errors[0]}`
        : `Imported ${added} file${added === 1 ? '' : 's'}.`,
    );
  };

  const handleText = () => {
    // Placed on the topmost free video track, creating one if needed.
    const id = addTextAtPlayhead();
    useTimelineStore.getState().select([id]);
    setStatus('Text clip added above your footage.');
  };

  return (
    <>
      {/* Narrow section switcher. */}
      <nav className="oc-sidebar">
        <button className="oc-sidebar-item is-active">Import</button>
        <button className="oc-sidebar-item" onClick={() => setTab('media')}>
          Media
        </button>
        <button className="oc-sidebar-item">Subprojects</button>
        <button className="oc-sidebar-item">
          Yours <FolderOpen size={13} />
        </button>
        <button className="oc-sidebar-item">
          Generate <Sparkles size={13} />
        </button>
        <button className="oc-sidebar-item">Spaces</button>
        <button className="oc-sidebar-item">Library</button>
      </nav>

      <aside className="oc-library">
        {/* Horizontal icon tabs, as on CapCut. */}
        <div className="oc-tabstrip">
          <button
            className={`oc-tab${tab === 'media' ? ' is-active' : ''}`}
            onClick={() => setTab('media')}
          >
            <Film size={17} />
            <span>Media</span>
          </button>
          <button
            className={`oc-tab${tab === 'text' ? ' is-active' : ''}`}
            onClick={() => setTab('text')}
          >
            <Type size={17} />
            <span>Text</span>
          </button>
          <button
            className={`oc-tab${tab === 'filters' ? ' is-active' : ''}`}
            onClick={() => setTab('filters')}
          >
            <Sparkles size={17} />
            <span>Filters</span>
          </button>
        </div>
{tab === 'media' && (
          <>
            {/* Solid bin, not a dashed outline. */}
            <label className="oc-dropzone">
              <Upload size={20} />
              <span className="oc-dropzone-title">
                {clipCount === 0 ? 'Import' : 'Add media'}
              </span>
              <span>Drag and drop videos, photos, and audio files here</span>
              <input
                type="file"
                accept="video/*,image/*,audio/*"
                multiple
                hidden
                onChange={(e) => {
                  const files = Array.from(e.target.files ?? []);
                  if (files.length) void handleMedia(files);
                  e.target.value = '';
                }}
              />
            </label>

            <div className="oc-divider-label">
              <span />
              No media? Create with these tools
              <span />
            </div>

            <div className="oc-tool-row">
              <button className="oc-tool-card">
                <Sparkles size={20} />
                Generate
              </button>
              <button className="oc-tool-card">
                <Users size={20} />
                AI avatars
              </button>
              <button className="oc-tool-card">
                <Video size={20} />
                Record
              </button>
            </div>

            <section className="oc-library-section" style={{ marginTop: 16 }}>
              <h3 className="oc-library-heading">Fonts</h3>
              <FileButton
                label="Upload font"
                accept=".ttf,.otf,.woff,.woff2,font/ttf,font/otf"
                multiple
                onFiles={(f) => void addFiles(f)}
              />
              {fonts.length > 0 && (
                <ul className="oc-font-list">
                  {fonts.map((f) => (
                    <li key={f.id}>
                      <span style={{ fontFamily: `"${f.family}"` }}>{f.name}</span>
                      <small>{f.fileName}</small>
                    </li>
                  ))}
                </ul>
              )}
            </section>
          </>
        )}

        {tab === 'text' && (
          <>
            <section className="oc-library-section">
              <h3 className="oc-library-heading">Add text</h3>
              <button
                className="oc-btn"
                draggable
                onDragStart={(e) => {
                  e.dataTransfer.setData('application/x-opencap-text', 'text');
                  e.dataTransfer.effectAllowed = 'copy';
                }}
                onClick={handleText}
              >
                <Wand2 size={16} /> Default
              </button>
              <p className="oc-hint">Click to add at the playhead, or drag onto the timeline.</p>
            </section>

            <section className="oc-library-section">
              <h3 className="oc-library-heading">Presets</h3>
              <div className="oc-preset-grid">
                {TEXT_PRESETS.map((p) => (
                  <button
                    key={p.id}
                    className="oc-preset"
                    title={`Apply ${p.label} to the selected text clip`}
                    onClick={() => {
                      const sel = useTimelineStore.getState().selection[0];
                      if (!sel) {
                        setStatus('Select a text clip first.');
                        return;
                      }
                      useTimelineStore.getState().setText(sel, p.patch);
                    }}
                  >
                    {p.label}
                  </button>
                ))}
              </div>
            </section>
          </>
        )}

        {tab === 'filters' && (
          <section className="oc-library-section">
            <h3 className="oc-library-heading">Looks</h3>
            <p className="oc-hint">Colour looks live in the Details panel. Select a clip to apply one.</p>
          </section>
        )}

        {status && <p className="oc-status">{status}</p>}
      </aside>
    </>
  );
};
