import { useEffect, useCallback, useRef, useState } from 'react';
import { useTimelineStore } from './store/useTimelineStore';
import { useHistoryStore } from './store/useHistoryStore';
import { Library } from './components/Library/Library';
import { Viewport } from './components/Viewport/Viewport';
import { Timeline } from './components/Timeline/Timeline';
import { Inspector } from './components/Inspector/Inspector';
import { ExportDialog } from './components/Common/ExportDialog';

export const App = () => {
  const [showExport, setShowExport] = useState(false);
  const past = useHistoryStore((s) => s.past.length);
  const future = useHistoryStore((s) => s.future.length);

  /**
   * Wire the history store to the timeline store.
   *
   * Undo/redo restore a snapshot into the timeline store; committing snapshots
   * that store first. Registered once so every edit can be reverted.
   */
  const restore = useTimelineStore((s) => s.restore);

  /**
   * Feed the document into the history stack.
   *
   * The history store is intentionally passive: it only moves snapshots
   * around. Something has to observe the timeline store and commit after each
   * edit, which is done here via a subscription rather than inside the store
   * itself so the engine layer stays free of React.
   *
   * The previous serialized document is kept in a ref so transient state such
   * as the playhead or a live slider drag does not push a redundant undo step.
   */
  const lastDoc = useRef<string | null>(null);

  useEffect(() => {
    // Seed `present` without creating an undo step: there is nothing yet to
    // revert to, so the first real edit becomes the initial undo target.
    const initial = useTimelineStore.getState().snapshot();
    lastDoc.current = JSON.stringify(initial);
    useHistoryStore.getState().reset(initial);

    const unsubscribe = useTimelineStore.subscribe((state) => {
      const doc = JSON.stringify(state.snapshot());
      if (doc === lastDoc.current) return;
      lastDoc.current = doc;
      useHistoryStore.getState().commit('Edit', state.snapshot());
    });

    return unsubscribe;
  }, []);

  const onUndo = useCallback(() => {
    const history = useHistoryStore.getState();
    if (history.past.length === 0) return;
    history.undo();
    const next = useHistoryStore.getState().present;
    if (next) {
      restore(next);
      // Keep the watcher in sync so restoring does not echo back as a new edit.
      lastDoc.current = JSON.stringify(next);
    }
  }, [restore]);

  const onRedo = useCallback(() => {
    const history = useHistoryStore.getState();
    if (history.future.length === 0) return;
    history.redo();
    const next = useHistoryStore.getState().present;
    if (next) {
      restore(next);
      lastDoc.current = JSON.stringify(next);
    }
  }, [restore]);

  // Ctrl+Z / Ctrl+Shift+Z, Ctrl+B to split, ignored while typing in a field.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = e.target as HTMLElement | null;
      if (el && ['INPUT', 'TEXTAREA', 'SELECT'].includes(el.tagName)) return;
      if ((e.ctrlKey || e.metaKey) && e.code === 'KeyZ') {
        e.preventDefault();
        if (e.shiftKey) onRedo();
        else onUndo();
      }
      if ((e.ctrlKey || e.metaKey) && e.code === 'KeyB') {
        e.preventDefault();
        useTimelineStore.getState().splitAtPlayhead();
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onUndo, onRedo]);

  return (
    <div className="oc-app">
      <header className="oc-topbar">
        <h1 className="oc-brand">OpenCap</h1>
        <span className="oc-topbar-title">{useTimelineStore((s) => s.settings.name)}</span>
        <div className="oc-topbar-actions">
          <button className="oc-btn" disabled={past === 0} onClick={onUndo}>
            Undo
          </button>
          <button className="oc-btn" disabled={future === 0} onClick={onRedo}>
            Redo
          </button>
          <button className="oc-btn oc-btn-primary" onClick={() => setShowExport(true)}>
            Export
          </button>
        </div>
      </header>

      <main className="oc-main">
        <Library />
        <Viewport />
        <Inspector />
      </main>

      <Timeline />

      {showExport && <ExportDialog onClose={() => setShowExport(false)} />}
    </div>
  );
};
